Input: {"question": "When was the Adriatic launched?", "original_source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0494-9858d3eba5fb:d00", "start": 0, "end": 77, "text": "RMS Adriatic (1906) RMS \"Adriatic\" was an ocean liner of the White Star Line."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0494-9858d3eba5fb:d00", "start": 78, "end": 167, "text": "She was the fourth of a quartet of ships measuring over 20,000 tons, dubbed The Big Four."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0494-9858d3eba5fb:d00", "start": 168, "end": 293, "text": "The ship was the only one of the four which was never the world's largest ship; however, she was the fastest of the Big Four."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0494-9858d3eba5fb:d00", "start": 294, "end": 382, "text": "\"Adriatic\" was the first ocean liner to have an indoor swimming pool and a Turkish bath."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0494-9858d3eba5fb:d00", "start": 383, "end": 493, "text": "She was built by Harland and Wolff and was launched on 20 September 1906 (the same day as the Cunard Line's )."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0494-9858d3eba5fb:d00", "start": 494, "end": 519, "text": "She set off on her maiden"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0494-9858d3eba5fb:d01", "start": 0, "end": 112, "text": "SS Adriatic (1871) SS \"Adriatic\" was the first of two White Star Line ocean liners to carry the name \"Adriatic\"."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0494-9858d3eba5fb:d01", "start": 113, "end": 312, "text": "The White Star Line's first four steamships, the (\"Oceanic\" (I), \"Atlantic\", \"Baltic\", and the \"Republic\") met with great success in the trans-Atlantic market, and the line decided to build two more."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0494-9858d3eba5fb:d01", "start": 313, "end": 453, "text": "The first of these was the SS \"Adriatic\", which was built by Harland and Wolff and launched on 17 October 1871; the second was the \"Celtic\"."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0494-9858d3eba5fb:d01", "start": 454, "end": 537, "text": "During the remainder of 1871 and the early part of 1872, \"Adriatic\" was fitted out."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0494-9858d3eba5fb:d01", "start": 538, "end": 577, "text": "As a part of this process, a technology"}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0494-9858d3eba5fb:d02", "start": 0, "end": 53, "text": "launched on 17 October 1871 ; the second was Celtic ."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0494-9858d3eba5fb:d02", "start": 54, "end": 149, "text": "History [ ] During the remainder of 1871 and the early part of 1872 , Adriatic was fitted out ."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0494-9858d3eba5fb:d02", "start": 150, "end": 230, "text": "As a part of this process , a technology new to that era was tried on the ship ."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0494-9858d3eba5fb:d02", "start": 231, "end": 352, "text": "Up to this point , ships ' cabins had been lit by oil lamps , but the builders decided to try new gas lamps on Adriatic ."}, "D3S5": {"document_number": 3, "doc_id": "ramdocs-0494-9858d3eba5fb:d02", "start": 353, "end": 459, "text": "A machine was added to the engine room to produce gas from coal , the first ship in the world to have such"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 0, "end": 49, "text": "returning on 23 August 1813, having left in 1811."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 50, "end": 84, "text": "The database has no other details."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 85, "end": 185, "text": "\"Lloyd's Register\" for 1814 shows \"Vittoria\", Southam, master and owner, and trade London—Mauritius."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 186, "end": 270, "text": "Thereafter she traded with the West Indies, the Mediterranean, and the Indian Ocean."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 271, "end": 370, "text": "Notes Citations References Adriatic (1811 ship) Adriatic was launched in 1811 in the United States."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 371, "end": 418, "text": "The British Royal Navy seized her in July 1812."}, "D4S7": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 419, "end": 480, "text": "She was sold in 1813 and her new owners named her \"Vittoria\"."}, "D4S8": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 481, "end": 554, "text": "She traded with the West Indies, the Mediterranean, and the Indian Ocean."}, "D4S9": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 555, "end": 583, "text": "She was last listed in 1834."}, "D4S10": {"document_number": 4, "doc_id": "ramdocs-0494-9858d3eba5fb:d03", "start": 584, "end": 608, "text": "On 12 July 1812, shortly"}}, "original_cards": [{"doc_id": "ramdocs-0494-9858d3eba5fb:d00", "card_id": "ramdocs-0494-9858d3eba5fb:d00:c0", "entity": "Adriatic", "scope": "launch date", "claim": "The Adriatic was launched on 20 September 1906.", "answer": "20 September 1906", "quote": "She was built by Harland and Wolff and was launched on 20 September 1906 (the same day as the Cunard Line's ).", "original_document_number": 1}, {"doc_id": "ramdocs-0494-9858d3eba5fb:d01", "card_id": "ramdocs-0494-9858d3eba5fb:d01:c0", "entity": "Adriatic", "scope": "launch date", "claim": "The SS \"Adriatic\" was launched on 17 October 1871.", "answer": "17 October 1871", "quote": "The first of these was the SS \"Adriatic\", which was built by Harland and Wolff and launched on 17 October 1871; the second was the \"Celtic\".", "original_document_number": 2}, {"doc_id": "ramdocs-0494-9858d3eba5fb:d02", "card_id": "ramdocs-0494-9858d3eba5fb:d02:c0", "entity": "Adriatic", "scope": "launch date", "claim": "The Adriatic was launched on 17 October 1871.", "answer": "17 October 1871", "quote": "launched on 17 October 1871 ; the second was Celtic .", "original_document_number": 3}, {"doc_id": "ramdocs-0494-9858d3eba5fb:d03", "card_id": "ramdocs-0494-9858d3eba5fb:d03:c0", "entity": "Adriatic", "scope": "launch", "claim": "Adriatic was launched in 1811 in the United States.", "answer": "1811", "quote": "Notes Citations References Adriatic (1811 ship) Adriatic was launched in 1811 in the United States.", "original_document_number": 4}], "current_answers": ["20 September 1906", "17 October 1871", "1811"], "candidate_answers": [{"candidate_id": "R0", "answer": "20 September 1906", "origin": "initial"}, {"candidate_id": "R1", "answer": "17 October 1871", "origin": "initial"}, {"candidate_id": "R2", "answer": "1811", "origin": "initial"}], "requested_slot_hint": "other"}
